mapper.select:
select sl.create_time, concat(concat(ur.username,'\/'),ur.firstname) as username,
sl.log_content as logContent, sl.ip
from ins_record_logs sl left join sys_users ur on sl.userid = ur.id
where sl.username !='gwm-admin'
and sl.app_id=#{syslog.appId}
and sl.create_time>=#{syslog.startDate} AND date_add(#{syslog.endDate}, interval 1 day)>=sl.create_time
and sl.userid=#{syslog.userid}
and sl.userid in
#{item}
and sud.dep_id =#{syslog.departid}
AND
( sl.log_content LIKE CONCAT('%', #{syslog.searchKeyword}, '%') or sl.username LIKE CONCAT('%', #{syslog.searchKeyword}, '%') )
order by create_time desc limit #{pageNum}, #{pageSize}

select count(1) from ins_record_logs sl left join sys_users ur on sl.userid = ur.id
where sl.username !='gwm-admin'
and sl.app_id=#{syslog.appId}
and sl.create_time>=#{syslog.startDate} AND date_add(#{syslog.endDate}, interval 1 day)>=sl.create_time
and sl.userid=#{syslog.userid}
and sud.dep_id =#{syslog.departid}
AND
( sl.log_content LIKE CONCAT('%', #{syslog.searchKeyword}, '%') or sl.username LIKE CONCAT('%', #{syslog.searchKeyword}, '%') )
order by sl.create_time desc
